code_after:
// ✅ Fixed: Defer browser-dependent state until after mount
const [time, setTime] = useState<string | null>(null);
useEffect(() => {
  setTime(new Date().toLocaleTimeString());
}, []);
return <div>Current time: {time ?? 'Loading...'}</div>;

