code_after:
// ✅ Fixed: Initialize with empty array and use optional chaining
const [items, setItems] = useState([]);
if (!items || items.length === 0) return <p>Loading items...</p>;
return <div>{items?.map(item => <p key={item.id}>{item.name}</p>)}</div>;

// ✅ Fixed: Use React Portal to escape local context and render at <body>
import { createPortal } from 'react-dom';
export function Modal({ children }) {
  if (typeof document === 'undefined') return null;
  return createPortal(
    <div className="fixed inset-0 z-50 bg-black/50 backdrop-blur">{children}</div>,
    document.body
  );
}

