code_after:
// ✅ Fixed: Calculate derived state or wrap in useEffect
function UserProfile({ user }) {
  // Method A: Derived state (simplest & best)
  const isActive = Boolean(user.isOnline);

  // Method B: If side-effect is strictly needed:
  const [active, setActive] = useState(false);
  useEffect(() => {
    setActive(Boolean(user.isOnline));
  }, [user.isOnline]);

  return <div>{user.name}</div>;
}
